changeSet.sql:
DROP VIEW IF EXISTS nexus.collection_health_meta;
ALTER TABLE nexus.catalog_documents ALTER COLUMN bib_enriched_at DROP DEFAULT, ALTER COLUMN bib_enriched_at DROP NOT NULL, ALTER COLUMN index_started_at DROP DEFAULT, ALTER COLUMN index_started_at DROP NOT NULL, ALTER COLUMN indexed_at TYPE timestamptz USING NULLIF(indexed_at, '')::timestamptz, ALTER COLUMN bib_enriched_at TYPE timestamptz USING NULLIF(bib_enriched_at, '')::timestamptz, ALTER COLUMN index_started_at TYPE timestamptz USING NULLIF(index_started_at, '')::timestamptz;
CREATE VIEW nexus.collection_health_meta WITH (security_invoker = true) AS SELECT d.tenant_id, d.physical_collection AS collection, max(d.indexed_at) AS last_indexed, count(*) FILTER ( WHERE NOT EXISTS ( SELECT 1 FROM nexus.catalog_links l WHERE l.to_tumbler = d.tumbler ) ) AS orphan_count, (count(*) FILTER (WHERE d.indexed_at IS NOT NULL AND d.indexed_at < now() - interval '30 days'))::double precision / NULLIF(count(*) FILTER (WHERE d.indexed_at IS NOT NULL), 0) AS stale_source_ratio FROM nexus.catalog_documents d WHERE d.physical_collection IS NOT NULL AND d.deleted_at IS NULL GROUP BY d.tenant_id, d.physical_collection;
GRANT SELECT ON nexus.collection_health_meta TO PUBLIC;
-- BUG-0148 invariant (rdr180-16-analyze-rewritten-tables precedent, mechanically -- enforced by tests/test_changelog_analyze_lint.py): the ALTER COLUMN ... TYPE -- above rewrites catalog_documents and resets its planner statistics — ANALYZE -- it in the same pass so a stale-stats plan flip cannot silently degrade -- collection_health_meta / hybrid-search queries the way BUG-0148 did. ANALYZE nexus.catalog_documents;

rollback.sql:
DROP VIEW IF EXISTS nexus.collection_health_meta;
ALTER TABLE nexus.catalog_documents ALTER COLUMN indexed_at TYPE TEXT USING to_char(indexed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'), ALTER COLUMN bib_enriched_at TYPE TEXT USING COALESCE(to_char(bib_enriched_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'), ''), ALTER COLUMN index_started_at TYPE TEXT USING COALESCE(to_char(index_started_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'), ''), ALTER COLUMN bib_enriched_at SET NOT NULL, ALTER COLUMN bib_enriched_at SET DEFAULT '', ALTER COLUMN index_started_at SET NOT NULL, ALTER COLUMN index_started_at SET DEFAULT '';
CREATE VIEW nexus.collection_health_meta WITH (security_invoker = true) AS SELECT d.tenant_id, d.physical_collection AS collection, max(d.indexed_at) AS last_indexed, count(*) FILTER ( WHERE NOT EXISTS ( SELECT 1 FROM nexus.catalog_links l WHERE l.to_tumbler = d.tumbler ) ) AS orphan_count, (count(*) FILTER ( WHERE d.indexed_at ~ '^[0-9]{4}-' AND d.indexed_at < to_char( (now() - interval '30 days') AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') ))::double precision / NULLIF(count(*) FILTER (WHERE d.indexed_at ~ '^[0-9]{4}-'), 0) AS stale_source_ratio FROM nexus.catalog_documents d WHERE d.physical_collection IS NOT NULL AND d.deleted_at IS NULL GROUP BY d.tenant_id, d.physical_collection;
GRANT SELECT ON nexus.collection_health_meta TO PUBLIC;
-- Same BUG-0148 discipline as the forward SQL above — the rollback's own -- ALTER COLUMN ... TYPE rewrites catalog_documents again. ANALYZE nexus.catalog_documents;

changeSet.sql:
ALTER TABLE nexus.catalog_links
    ALTER COLUMN created_at TYPE timestamptz
    USING NULLIF(created_at, '')::timestamptz;
ANALYZE nexus.catalog_links;

