    ALTER COLUMN created_at TYPE TEXT
    USING to_char(created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"');
ANALYZE nexus.catalog_links;

changeSet.sql:
ALTER TABLE nexus.catalog_collections
    ALTER COLUMN legacy_grandfathered DROP DEFAULT;
ALTER TABLE nexus.catalog_collections
    ALTER COLUMN legacy_grandfathered TYPE boolean
    USING (legacy_grandfathered <> 0);
ALTER TABLE nexus.catalog_collections
    ALTER COLUMN legacy_grandfathered SET DEFAULT false;
ANALYZE nexus.catalog_collections;

